	@ParameterizedTest
	@ValueSource(strings = { "GET_NAMESPACE", "GET_NAMESPACES", "SET_NAMESPACE", "REMOVE_NAMESPACE",
			"CLEAR_NAMESPACES" })
	void namespaceActionsRejectDeleteWithoutEndingTheTransaction(String action) {
		MockHttpServletRequest request = request(action, "ex", CHANGED);
		request.setMethod("DELETE");
		assertThatThrownBy(() -> controller.handleRequest(request, new MockHttpServletResponse()))
				.isInstanceOfSatisfying(ClientHTTPException.class,
						failure -> assertThat(failure.getStatusCode()).isEqualTo(405));
		assertThat(ActiveTransactionRegistry.INSTANCE.getTransaction(transaction.getID())).isSameAs(transaction);
		assertThat(transaction.isClosed()).isFalse();
	}

	@ParameterizedTest
	@ValueSource(strings = { "rdf", "wn-6", "t_1", "a.3" })
	void namespacePrefixValidationAcceptsTheStandaloneEndpointGrammar(String prefix) throws Exception {
		perform("SET_NAMESPACE", prefix, CHANGED);
		assertThat(namespace(prefix)).isEqualTo(CHANGED);
	}

	@ParameterizedTest
	@MethodSource("invalidNamespaceUpdates")
	void namespaceValidationMatchesTheStandaloneEndpoint(String prefix, String name, String message) {
		assertThatThrownBy(() -> perform("SET_NAMESPACE", prefix, name))
				.isInstanceOfSatisfying(ClientHTTPException.class,
						failure -> assertThat(failure.getStatusCode()).isEqualTo(400))
				.hasMessageContaining(message);
		assertCommittedNamespaces(Map.of("ex", ORIGINAL));
	}

	static Stream<Arguments> invalidNamespaceUpdates() {
		return Stream.of(
				Arguments.of("2a", CHANGED, "Prefix not valid"),
				Arguments.of("_prefix", CHANGED, "Prefix not valid"),
				Arguments.of("rdf 4j", CHANGED, "Prefix not valid"),
				Arguments.of("ex", "", "No namespace name found in request body"),
				Arguments.of("ex", " \t\n", "No namespace name found in request body"),
				Arguments.of("ex", "relative/namespace", "Namespace not valid"),
				Arguments.of("ex", "http://example.org/with whitespace", "Namespace not valid"));
	}

	private String namespace(String prefix) throws Exception {
		return (String) perform("GET_NAMESPACE", prefix, null).getModel().get(SimpleResponseView.CONTENT_KEY);
	}

	private void assertMissingNamespace(String prefix) {
		assertThatThrownBy(() -> perform("GET_NAMESPACE", prefix, null))
				.isInstanceOfSatisfying(ClientHTTPException.class,
						failure -> assertThat(failure.getStatusCode()).isEqualTo(404));
	}

	private Map<String, String> namespaces() throws Exception {
		ModelAndView result = perform("GET_NAMESPACES", null, null);
		try (TupleQueryResult rows = (TupleQueryResult) result.getModel().get(QueryResultView.QUERY_RESULT_KEY)) {
			return readNamespaces(rows);
		}
	}

	private Map<String, String> readNamespaces(TupleQueryResult rows) {
		assertThat(rows.getBindingNames()).containsExactly("prefix", "namespace");
		Map<String, String> namespaces = new HashMap<>();
		while (rows.hasNext()) {
			var row = rows.next();
			namespaces.put(row.getValue("prefix").stringValue(), row.getValue("namespace").stringValue());
		}
		return namespaces;
	}

	private void assertCommittedNamespaces(Map<String, String> expected) {
		try (var connection = repository.getConnection(); var rows = connection.getNamespaces()) {
			Map<String, String> namespaces = new HashMap<>();
			while (rows.hasNext()) {
				Namespace namespace = rows.next();
				namespaces.put(namespace.getPrefix(), namespace.getName());
			}
			assertThat(namespaces).containsExactlyInAnyOrderEntriesOf(expected);
		}
	}

	private ModelAndView perform(String action, String prefix, String body) throws Exception {
		return controller.handleRequest(request(action, prefix, body), new MockHttpServletResponse());
	}

	private MockHttpServletRequest request(String action, String prefix, String body) {
		String path = "/repositories/" + REPOSITORY_ID + "/transactions/" + transaction.getID();
		MockHttpServletRequest request = new MockHttpServletRequest("PUT", path);
		request.setPathInfo(path);
		request.setAttribute("repositoryID", REPOSITORY_ID);
		request.setAttribute("repository", repository);
		request.setParameter(Protocol.ACTION_PARAM_NAME, action);
		request.addHeader("Accept", "application/sparql-results+json");
		if (prefix != null) {
			request.setParameter("prefix", prefix);
		}
		if (body != null) {
			request.setContentType("text/plain");
			request.setCharacterEncoding(UTF_8.name());
			request.setContent(body.getBytes(UTF_8));
		}
		return request;
	}

	private void closeTransaction() throws Exception {
		if (transaction != null) {
			try (Transaction closing = transaction) {
				ActiveTransactionRegistry.INSTANCE.deregister(closing);
			} finally {
				transaction = null;
			}
		}
	}

	private static final class TrackingRepository extends RepositoryWrapper {
		private final AtomicInteger namespaceResultCloses = new AtomicInteger();
		private final AtomicReference<Thread> namespaceIteratorOwner = new AtomicReference<>();
		private final AtomicBoolean namespaceIteratorCrossedThreads = new AtomicBoolean();

		private TrackingRepository() {
			super(new SailRepository(new MemoryStore()));
		}

		@Override
		public RepositoryConnection getConnection() {
			return new RepositoryConnectionWrapper(this, super.getConnection()) {
				@Override
				public RepositoryResult<Namespace> getNamespaces() {
					RepositoryResult<Namespace> rows = super.getNamespaces();
					Thread owner = Thread.currentThread();
					namespaceIteratorOwner.set(owner);
					return new RepositoryResult<>(new CloseableIteration<Namespace>() {
						private void recordThread() {
							if (Thread.currentThread() != owner) {
								namespaceIteratorCrossedThreads.set(true);
							}
						}

						@Override
						public boolean hasNext() {
							recordThread();
							return rows.hasNext();
						}

						@Override
						public Namespace next() {
							recordThread();
							return rows.next();
						}

						@Override
						public void remove() {
							recordThread();
							rows.remove();
						}

						@Override
						public void close() {
							recordThread();
							try {
								rows.close();
							} finally {
								namespaceResultCloses.incrementAndGet();
							}
						}
					});
				}
			};
		}
	}
